ids = await orders_list_order_ids()
futs = [orders_get_order(order_id=i) for i in ids]
rows = [await f for f in futs]
tot = {}
odd = []
for r in rows:
    reg = r.get("region"); a = r.get("amount")
    if not isinstance(a,(int,float)) or reg is None: odd.append({k:v for k,v in r.items() if k!="detail"})
    tot[reg] = tot.get(reg,0)+(a if isinstance(a,(int,float)) else 0)
return {"n":len(rows),"tot":{k:round(v,2) for k,v in tot.items()},"odd":odd,"keys":sorted({k for r in rows for k in r})}

